registry = {
    'ghcr.io/alice/where-am-i': {
        'visibility': 'public',
        'tags': {'1.0': ['linux/amd64', 'linux/arm64'], 'latest': ['linux/arm64']}
    },
    'ghcr.io/bob/secret-app': {
        'visibility': 'private',
        'tags': {'1.0': ['linux/amd64']}
    }
}

def resolve_pull(image_ref, host_arch, reg):
    if ':' in image_ref:
        repo_path, tag = image_ref.rsplit(':', 1)
    else:
        repo_path, tag = image_ref, 'latest'
    if repo_path != repo_path.lower():
        return 'ERROR: repository name must be lowercase'
    pkg = reg.get(repo_path)
    if not pkg or pkg['visibility'] == 'private':
        return 'ERROR: denied or not found'
    arches = pkg['tags'].get(tag)
    if arches is None:
        return 'ERROR: manifest unknown'
    if host_arch not in arches:
        return f'ERROR: no matching manifest for {host_arch}'
    return f'PULLED {repo_path}:{tag} ({host_arch})'

print(resolve_pull('ghcr.io/alice/where-am-i:1.0', 'linux/amd64', registry))
print(resolve_pull('ghcr.io/Alice/where-am-i:1.0', 'linux/amd64', registry))
print(resolve_pull('ghcr.io/bob/secret-app:1.0', 'linux/amd64', registry))
