function buildDockerRun(cfg) {
  const parts = ['docker', 'run'];
  if (cfg.detach) parts.push('-d');
  if (cfg.interactive) parts.push('-it');
  if (cfg.autoRemove) parts.push('--rm');
  if (cfg.hostPort && cfg.containerPort) parts.push(`-p ${cfg.hostPort}:${cfg.containerPort}`);
  if (cfg.volume) parts.push(`-v ${cfg.volume}`);
  if (cfg.network) parts.push(`--network ${cfg.network}`);
  if (cfg.name) parts.push(`--name ${cfg.name}`);
  parts.push(cfg.image);
  if (cfg.args && cfg.args.length > 0) parts.push(...cfg.args);
  return parts.join(' ');
}

console.log(buildDockerRun({
  detach: true,
  hostPort: 8080,
  containerPort: 80,
  name: 'web',
  image: 'nginx:1.30'
}));

console.log(buildDockerRun({
  interactive: true,
  autoRemove: true,
  volume: './data:/data',
  network: 'dai-net',
  image: 'ghcr.io/alice/cli:1.0',
  args: ['--loop']
}));

