services_cfg = {
    'web': {'ports': ['8080:80'], 'volumes': ['./html:/usr/share/nginx/html'], 'depends_on': ['api']},
    'api': {'ports': ['8080:7000'], 'volumes': ['app-cache:/cache'], 'depends_on': ['cache']},
    'db':  {'ports': [], 'volumes': ['db-data:/var/lib/postgresql/data'], 'depends_on': []}
}
top_volumes = {'db-data'}

def lint_compose(services, top_vols):
    errors = set()
    used_host_ports = set()
    for svc in services.values():
        for p in svc.get('ports', []):
            host_port = p.split(':')[0]
            if host_port in used_host_ports:
                errors.add(f'PORT_COLLISION: {host_port}')
            used_host_ports.add(host_port)
        for v in svc.get('volumes', []):
            src = v.split(':')[0]
            if not (src.startswith('./') or src.startswith('/')) and src not in top_vols:
                errors.add(f'UNDECLARED_VOLUME: {src}')
        for dep in svc.get('depends_on', []):
            if dep not in services:
                errors.add(f'UNKNOWN_DEP: {dep}')
    return sorted(errors)

for err in lint_compose(services_cfg, top_volumes):
    print(err)
